-- ============================================================================
-- Path Finder - the registrar's prospectus, loaded once.
-- 12 programs, 364 subjects, 647 placements (program x year x semester).
-- Generated from the registrar's curriculum export; reference data, not
-- edited in the app. Each program links to its library program so students
-- open their own curriculum first.
-- ============================================================================
begin;

-- Programs (prospectus code -> the library's program of the same name)

-- Subjects

-- Placements: where each subject sits in a program's year + semester

-- Keep the identity sequences ahead of the explicit ids.
select setval(pg_get_serial_sequence('public.curriculum_programs','id'), (select max(id) from public.curriculum_programs));
select setval(pg_get_serial_sequence('public.curriculum_subjects','id'), (select max(id) from public.curriculum_subjects));

-- Sanity check: the expected counts must land exactly.
do $$
begin
  if (select count(*) from public.curriculum_programs) <> 12 then
    raise exception 'Expected 12 curriculum programs.';
  end if;
  if (select count(*) from public.curriculum_subjects) <> 364 then
    raise exception 'Expected 364 curriculum subjects.';
  end if;
  if (select count(*) from public.curriculum_entries) <> 647 then
    raise exception 'Expected 647 curriculum entries.';
  end if;
end $$;

commit;
